import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();
// The SDK automatically reads ANTHROPIC_API_KEY from the environment

const message = await client.messages.create({
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 200,
  messages: [
    {
      role: 'user',
      content: 'What is the most exciting thing about AI in 2025? One paragraph.'
    }
  ]
});

console.log(message.content[0].text);

## Async Usage in Node.js

The `await` keyword means the SDK call is asynchronous — it doesn't block while waiting for the response. This matters when you build applications that make multiple API calls or handle user input while waiting.

The script above works with `await` at the top level because modern Node.js supports top-level await in ES modules. If you're inside a function, wrap it:

```javascript
async function askClaude(question) {
  const message = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 200,
    messages: [{ role: 'user', content: question }]
  });
  return message.content[0].text;
}

const answer = await askClaude('What is recursion?');
console.log(answer);
```
